def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([7]), fmt([-7]), fmt([5, 5, 5, 5]), fmt([1, 2]), fmt([2, 1]),
             fmt([-10**9, 10**9]), fmt([10**9, -10**9, 0]), fmt([-3, -8, -1, -8])]
    for n in (2, 3, 5, 8, 12, 20, 30):
        for _ in range(2):
            lo = rng.choice([-10, 0, -100])
            tests.append(fmt([rng.randint(lo, lo + rng.choice([5, 50, 1000])) for _ in range(n)]))
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(100000)]))
    tests.append(fmt([rng.randint(-10**9, -10**9 + 5) for _ in range(100000)]))
    a = [rng.randint(-10**9, 10**9) for _ in range(100000)]
    a[0], a[-1] = 10**9, -10**9
    tests.append(fmt(a))
    tests.append(fmt([10**9] * 100000))
    return tests
